#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kFloat32,
        name, " must have float32 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

static void check_bf16_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kBFloat16,
        name, " must have bfloat16 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. definition.json declares:
//   freqs             : [batch_size, seq_len, half_head_dim] fp32
//   attention_scaling : scalar fp32
//   cos               : [batch_size, seq_len, head_dim] bf16 (DPS)
//   sin               : [batch_size, seq_len, head_dim] bf16 (DPS)
//
// head_dim is constant at 128 per definition.json; half_head_dim
// is the derived axis head_dim // 2 = 64.
void run(
    const torch::Tensor& freqs,
    double attention_scaling,
    torch::Tensor cos,
    torch::Tensor sin
) {
    TORCH_CHECK(freqs.dim() == 3, "freqs must be 3D [batch, seq, half_head_dim]");
    TORCH_CHECK(cos.dim() == 3, "cos must be 3D");
    TORCH_CHECK(sin.dim() == 3, "sin must be 3D");

    const int64_t half_head_dim = freqs.size(2);
    const int64_t head_dim = cos.size(2);
    TORCH_CHECK(
        head_dim == 2 * half_head_dim,
        "head_dim must equal 2 * half_head_dim; got head_dim=",
        head_dim, " half_head_dim=", half_head_dim);
    TORCH_CHECK(
        cos.size(0) == freqs.size(0) && cos.size(1) == freqs.size(1),
        "cos shape must match freqs leading dims");
    TORCH_CHECK(
        sin.size(0) == freqs.size(0) && sin.size(1) == freqs.size(1),
        "sin shape must match freqs leading dims");
    TORCH_CHECK(
        sin.size(2) == head_dim,
        "sin head_dim must match cos head_dim");

    check_fp32_contiguous_cuda(freqs, "freqs");
    check_bf16_contiguous_cuda(cos, "cos");
    check_bf16_contiguous_cuda(sin, "sin");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_012_fused_cos_sin_launcher(
        freqs,
        static_cast<float>(attention_scaling),
        cos,
        sin,
        stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "Fused cos/sin embedding generation for RoPE: "
        "emb = cat(freqs, freqs); cos = bf16(cos(emb) * scale); "
        "sin = bf16(sin(emb) * scale). Destination-passing style.");
}

#include "kernel.h"
#include <cuda_bf16.h>
#include <cuda_runtime.h>

// One thread per (head_dim) output position; one block per (batch,
// seq) row. The reference performs emb = cat(freqs, freqs) along
// the last dim then sin/cos with attention scaling. We fold the
// replication into the index math: for lane d in [0, head_dim),
// the input index is d % half_head_dim, so lanes [0, half) and
// [half, head_dim) read freqs at the same position. Each thread
// emits one cos element and one sin element.

namespace {

constexpr int BLOCK_THREADS = 128;  // head_dim baked at the spec value

__global__ void problem_012_fused_cos_sin_kernel(
    const float* __restrict__ freqs,
    __nv_bfloat16* __restrict__ cos_out,
    __nv_bfloat16* __restrict__ sin_out,
    int row_count,
    int half_head_dim,
    int head_dim,
    float attention_scaling) {

    const int row = blockIdx.x;
    if (row >= row_count) {
        return;
    }
    const int d = threadIdx.x;
    if (d >= head_dim) {
        return;
    }

    const int freq_idx = d < half_head_dim ? d : d - half_head_dim;
    const float x = freqs[row * half_head_dim + freq_idx];

    float c, s;
    __sincosf(x, &s, &c);
    c *= attention_scaling;
    s *= attention_scaling;

    const int out_offset = row * head_dim + d;
    cos_out[out_offset] = __float2bfloat16_rn(c);
    sin_out[out_offset] = __float2bfloat16_rn(s);
}

}  // namespace

void problem_012_fused_cos_sin_launcher(
    const torch::Tensor& freqs,
    float attention_scaling,
    torch::Tensor& cos_out,
    torch::Tensor& sin_out,
    cudaStream_t stream) {

    const int batch_size = static_cast<int>(freqs.size(0));
    const int seq_len = static_cast<int>(freqs.size(1));
    const int half_head_dim = static_cast<int>(freqs.size(2));
    const int head_dim = static_cast<int>(cos_out.size(2));
    const int row_count = batch_size * seq_len;

    dim3 grid(row_count);
    dim3 block(BLOCK_THREADS);

    problem_012_fused_cos_sin_kernel<<<grid, block, 0, stream>>>(
        freqs.data_ptr<float>(),
        reinterpret_cast<__nv_bfloat16*>(cos_out.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(sin_out.data_ptr<at::BFloat16>()),
        row_count,
        half_head_dim,
        head_dim,
        attention_scaling);
}

#pragma once

#ifndef PROBLEM_012_FUSED_COS_SIN_EMBEDDING_GENERATION_KERNEL_H
#define PROBLEM_012_FUSED_COS_SIN_EMBEDDING_GENERATION_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher for the fused cos/sin embedding generation.
// freqs is [batch_size, seq_len, half_head_dim] FP32 contiguous.
// cos / sin are pre-allocated [batch_size, seq_len, head_dim] BF16
// outputs (destination-passing style). head_dim = 2 * half_head_dim;
// the emb = cat(freqs, freqs) replication is folded into the index
// math so freqs is read only once per element.
void problem_012_fused_cos_sin_launcher(
    const torch::Tensor& freqs,
    float attention_scaling,
    torch::Tensor& cos_out,
    torch::Tensor& sin_out,
    cudaStream_t stream);

#endif  // PROBLEM_012_FUSED_COS_SIN_EMBEDDING_GENERATION_KERNEL_H
